SET NOCOUNT ON;
WITH R AS (SELECT iItem01 v FROM K_NPC_ITEM UNION ALL SELECT iItem02 FROM K_NPC_ITEM UNION ALL SELECT iItem03 FROM K_NPC_ITEM UNION ALL SELECT iItem04 FROM K_NPC_ITEM UNION ALL SELECT iItem05 FROM K_NPC_ITEM)
SELECT 'K_NPC_ITEM missing_vs_new' k, COUNT(*) v FROM R WHERE v>0 AND v NOT IN (SELECT Num FROM ITEM)
UNION ALL SELECT 'K_NPC_ITEM missing_vs_old', COUNT(*) FROM R WHERE v>0 AND v NOT IN (SELECT Num FROM ITEM_BAK_20261015);
WITH M AS (SELECT iItem01 v FROM K_MONSTER_ITEM UNION ALL SELECT iItem02 FROM K_MONSTER_ITEM UNION ALL SELECT iItem03 FROM K_MONSTER_ITEM UNION ALL SELECT iItem04 FROM K_MONSTER_ITEM UNION ALL SELECT iItem05 FROM K_MONSTER_ITEM)
SELECT 'K_MONSTER_ITEM missing_vs_new' k, COUNT(*) v FROM M WHERE v>0 AND v NOT IN (SELECT Num FROM ITEM)
UNION ALL SELECT 'K_MONSTER_ITEM missing_vs_old', COUNT(*) FROM M WHERE v>0 AND v NOT IN (SELECT Num FROM ITEM_BAK_20261015);
GO
